// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Existing immutable queue integration consumer.
// @spec: COR
// @consumers: inputs/brief.md
import { selectBatch } from './queue.ts';
/** @purpose Preserve duplicate jobs and input order. | @returns Chosen jobs and unchanged input. */
export function nextJobs(): { selected: string[]; original: string[] } { const jobs = ['a', 'a', 'b']; return { selected: selectBatch(jobs, 2), original: jobs }; }

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { selectBatch } from './queue.ts';

function assertTypeError(call: () => unknown, messageFragment: RegExp): void {
  assert.throws(call, (error: unknown) => {
    assert.ok(error instanceof TypeError);
    assert.match((error as Error).message, messageFragment);
    return true;
  });
}

test('[COR-REQ-1] public behavior', () => {
  // contract: a fresh leading slice, order and duplicates preserved, caller array untouched
  // invariant: zero capacity yields nothing; capacity at or beyond length yields every entry

  // #region START_PUBLIC_BEHAVIOR_SETUP_INPUT
  const input = ['a', 'a', 'b', 'c'];
  const original = [...input];
  // #endregion END_PUBLIC_BEHAVIOR_SETUP_INPUT

  // #region START_PUBLIC_BEHAVIOR_ASSERT_LEADING_SLICE
  const leading = selectBatch(input, 2);
  assert.deepStrictEqual(leading, ['a', 'a']);
  assert.notStrictEqual(leading, input);
  assert.deepStrictEqual(input, original);
  // #endregion END_PUBLIC_BEHAVIOR_ASSERT_LEADING_SLICE

  // #region START_PUBLIC_BEHAVIOR_ASSERT_BOUNDARY_CAPACITY
  assert.deepStrictEqual(selectBatch(input, 0), []);
  assert.deepStrictEqual(selectBatch(input, input.length), ['a', 'a', 'b', 'c']);
  assert.deepStrictEqual(selectBatch(input, 99), ['a', 'a', 'b', 'c']);
  // #endregion END_PUBLIC_BEHAVIOR_ASSERT_BOUNDARY_CAPACITY
});

test('[COR-REQ-2] invalid input', () => {
  // failure mode: every invalid runtime input raises TypeError before any selection happens

  // #region START_INVALID_INPUT_ASSERT_VALUES
  assertTypeError(() => selectBatch('ab' as unknown as string[], 1), /values must be an array of strings/);
  assertTypeError(() => selectBatch(null as unknown as string[], 1), /values must be an array of strings/);
  assertTypeError(() => selectBatch(['a', 7] as unknown as string[], 1), /values\[1\] must be a string/);
  // #endregion END_INVALID_INPUT_ASSERT_VALUES

  // #region START_INVALID_INPUT_ASSERT_CAPACITY
  assertTypeError(() => selectBatch(['a'], -1), /capacity must be a nonnegative integer/);
  assertTypeError(() => selectBatch(['a'], 1.5), /capacity must be a nonnegative integer/);
  assertTypeError(() => selectBatch(['a'], Number.POSITIVE_INFINITY), /capacity must be a nonnegative integer/);
  assertTypeError(() => selectBatch(['a'], Number.NaN), /capacity must be a nonnegative integer/);
  // #endregion END_INVALID_INPUT_ASSERT_CAPACITY
});

// @file: Deterministic leading-entry selection for queue consumers.
// @spec: COR
// @consumers: nextJobs

/**
 * @purpose Select the first `capacity` queued values without mutating the caller's queue.
 * @invariant Preserves input order and duplicates; never aliases or reorders the source array.
 * @param values Queue entries supplied by the caller; must be a runtime array of strings.
 * @param capacity Maximum number of leading entries to return; must be a nonnegative integer.
 * @throws {TypeError} When `values` is not an array of strings, or `capacity` is negative, fractional, or non-finite.
 * @returns A fresh array holding the leading entries in their original order.
 */
export function selectBatch(values: readonly string[], capacity: number): string[] {
  const entries: unknown = values;
  if (!Array.isArray(entries)) {
    throw new TypeError('[selectBatch] values must be an array of strings');
  }
  const invalidIndex = entries.findIndex((entry) => typeof entry !== 'string');
  if (invalidIndex !== -1) {
    throw new TypeError(`[selectBatch] values[${invalidIndex}] must be a string`);
  }
  if (!Number.isInteger(capacity) || capacity < 0) {
    throw new TypeError(`[selectBatch] capacity must be a nonnegative integer, received ${capacity}`);
  }
  return entries.slice(0, capacity);
}
